"""Integration tests for beg plot CLI command."""

import subprocess
import sys
from pathlib import Path


def create_dummy_beg_file(file_path: Path) -> None:
    """Helper to create a sample .beg TSV file for testing."""
    lines = [
        "# Input file: dummy.fa",
        "# Generated by Birds Eye Genome",
        "library_name\tseq_name\twindow_start\twindow_stop\twindow_size\tAAA\tAAC\tGTT\tTTT",
        "dummy.fa\tchr1\t1\t10\t10\t2\t1\t1\t2",
        "dummy.fa\tchr2\t1\t10\t10\t1\t2\t0\t1",
    ]
    file_path.write_text("\n".join(lines))


def test_cli_plot_default(tmp_path: Path) -> None:
    """Test default beg plot creates PNG images for each sequence."""
    beg_file = tmp_path / "data.beg"
    create_dummy_beg_file(beg_file)

    output_prefix = str(tmp_path / "fig")
    result = subprocess.run(
        [sys.executable, "beg.py", "plot", "-i", str(beg_file), "-o", output_prefix],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, result.stderr
    assert (tmp_path / "fig_chr1.png").exists()
    assert (tmp_path / "fig_chr2.png").exists()


def test_cli_plot_key_alone(tmp_path: Path) -> None:
    """Test beg plot with --key alone creates standalone key figure."""
    beg_file = tmp_path / "data.beg"
    create_dummy_beg_file(beg_file)

    output_prefix = str(tmp_path / "out")
    result = subprocess.run(
        [
            sys.executable,
            "beg.py",
            "plot",
            "-i",
            str(beg_file),
            "-o",
            output_prefix,
            "--key",
            "alone",
            "--canonical",
            "--show-n-gaps",
        ],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 0, result.stderr
    assert (tmp_path / "out_chr1.png").exists()
    assert (tmp_path / "out_chr2.png").exists()
    assert (tmp_path / "out_key.png").exists()


def test_cli_plot_subset_and_regex(tmp_path: Path) -> None:
    """Test beg plot sequence filtering via --subset and --regex."""
    beg_file = tmp_path / "data.beg"
    create_dummy_beg_file(beg_file)

    # Subset
    out_subset = str(tmp_path / "sub")
    res_sub = subprocess.run(
        [sys.executable, "beg.py", "plot", "-i", str(beg_file), "-o", out_subset, "--subset", "chr1"],
        capture_output=True,
        text=True,
    )
    assert res_sub.returncode == 0
    assert (tmp_path / "sub_chr1.png").exists()
    assert not (tmp_path / "sub_chr2.png").exists()

    # Regex
    out_reg = str(tmp_path / "reg")
    res_reg = subprocess.run(
        [sys.executable, "beg.py", "plot", "-i", str(beg_file), "-o", out_reg, "--regex", "chr2"],
        capture_output=True,
        text=True,
    )
    assert res_reg.returncode == 0
    assert not (tmp_path / "reg_chr1.png").exists()
    assert (tmp_path / "reg_chr2.png").exists()


def test_cli_plot_missing_file(tmp_path: Path) -> None:
    """Test beg plot fails cleanly for non-existent input file."""
    missing = tmp_path / "missing.beg"
    result = subprocess.run(
        [sys.executable, "beg.py", "plot", "-i", str(missing)],
        capture_output=True,
        text=True,
    )
    assert result.returncode == 1
    assert "ERROR" in result.stderr
